CREATE TABLE version_origins (version_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, parent_version_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('MANUAL_DRAFT','ACTIVATED')), source_key TEXT NOT NULL, approval_hash TEXT, actor_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(parent_version_id,project_id) REFERENCES project_versions(id,project_id), UNIQUE(project_id,parent_version_id,kind,source_key));
CREATE TABLE job_sources (job_id TEXT NOT NULL, project_id TEXT NOT NULL, version_id TEXT NOT NULL, source_job_id TEXT NOT NULL, PRIMARY KEY(job_id,source_job_id), FOREIGN KEY(job_id,project_id,version_id) REFERENCES jobs(id,project_id,version_id), FOREIGN KEY(source_job_id,project_id,version_id) REFERENCES jobs(id,project_id,version_id));
